mapper.update:
update colaborador
set nombre=#{nombre}, apellidoPaterno=#{apellidoPaterno}, apellidoMaterno=#{apellidoMaterno},
curp=#{curp}, correo=#{correo}, idRol=#{idRol}, numeroLicencia=#{numeroLicencia}
where idColaborador=#{idColaborador};

mapper.select:
select idColaborador, to_base64(fotografia) as 'fotoBase64'
from colaborador
where idColaborador=#{idColaborador}
